#include <cstdint>
#include <cstring>
#include <iostream>

struct Monster
{
    virtual ~Monster() = default;
    virtual void update() {}
    virtual int damage() { return 1; }
};

struct Goblin : Monster
{
    int damage() override { return 3; }
};

int main()
{
    Goblin g{};
    void* vptr{};
    std::memcpy(&vptr, &g, sizeof vptr);
    std::cout << vptr << '\n';
}
